import{_ as i,o as n,c as u,a2 as t}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Vigezo vya Utambuzi wa Uhai wa Ajabu","description":"","frontmatter":{},"headers":[],"relativePath":"sw/53-奇特生命识别标准.md","filePath":"sw/53-奇特生命识别标准.md","lastUpdated":null}'),h={name:"sw/53-奇特生命识别标准.md"};function e(o,a,w,l,s,k){return n(),u("div",null,[...a[0]||(a[0]=[t('<h1 id="vigezo-vya-utambuzi-wa-uhai-wa-ajabu" tabindex="-1">Vigezo vya Utambuzi wa Uhai wa Ajabu <a class="header-anchor" href="#vigezo-vya-utambuzi-wa-uhai-wa-ajabu" aria-label="Permalink to &quot;Vigezo vya Utambuzi wa Uhai wa Ajabu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>53</td></tr><tr><td>Moduli</td><td>Kabila na Aina za Uhai</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Uhai wa ajabu, vigezo vya utambuzi, uainishaji wa kiwango, tathmini ya hatari, uamuzi wa asili</td></tr></tbody></table><h2 id="_1-ufafanuzi-na-wigo-wa-uhai-wa-ajabu" tabindex="-1">1. Ufafanuzi na Wigo wa Uhai wa Ajabu <a class="header-anchor" href="#_1-ufafanuzi-na-wigo-wa-uhai-wa-ajabu" aria-label="Permalink to &quot;1. Ufafanuzi na Wigo wa Uhai wa Ajabu&quot;">​</a></h2><p>Katika Hengyuanzhou (Ulimwengu wa Asili wa Viumbe Vyote), &quot;uhai wa ajabu&quot; unarejelea aina za uhai zisizojulikana ambazo haziwezi kupanguliwa katika makundi matano ya sasa ya nasaba za kabila zote (kabila ya mambo ya msingi ya kaboni, kabila ya mwongozo wa nishati, kabila ya muundo wa mitambo, kabila ya taarifa za fahamu, kabila ya mabadiliko ya mchanganyiko), au aina za uhai ambazo zinaweza kupanguliwa katika kategoria fulani lakini zina sifa za kigeni zinazoweza kuwa na athari kubwa kwa utaratibu wa asili.</p><p>Vyanzo vya uhai wa ajabu ni anuwai, ikiwa ni pamoja na lakini sio mdahani wa: uzalishaji wa asili katika mapasuko ya nafasi, matokeo yasiyotarajiwa ya majaribio ya nishati ya juu, uhai wa nje wa uvamizi kutoka nafasi nyingine, uhai wa kale ulioamka kutoka mabonde ya kale, aina mpya za uhai zinazozalishwa kutoka ukiukaji wa sheria, n.k. Kwa sababu ya kutojulikana na hatari inayowezekana ya uhai wa ajabu, uanzishaji wa vigezo vya utambuzi vya kisayansi na vikali ni masharti ya awali ya kuhakikisha usalama wa asili.</p><h2 id="_2-kanuni-za-msingi-za-utambuzi" tabindex="-1">2. Kanuni za Msingi za Utambuzi <a class="header-anchor" href="#_2-kanuni-za-msingi-za-utambuzi" aria-label="Permalink to &quot;2. Kanuni za Msingi za Utambuzi&quot;">​</a></h2><p>Utambuzi wa uhai wa ajabu unafuata kanuni zifuatazo za msingi:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maana ya ndani</th></tr></thead><tbody><tr><td>Kanuni ya Tabanio la Mwangalifu</td><td>Kabla ya utambuzi kamili kukamilika, uhai wa ajabu unachukuliwa kama ukiwa na hatari inayowezekana, na hatua za utengamano na uchunguzi zinachukuliwa</td></tr><tr><td>Kanuni ya Tathmini ya Vipengele Vingi</td><td>Tathmani kamili kutoka vipengele vingi kama vile umbo la uhai, sifa za nishati, mtindo wa tabia, kiwango cha fahamu, kiwango cha hatari, n.k.</td></tr><tr><td>Kanuni ya Kutotofautisha</td><td>Lengo la utambuzi ni tathmini ya hatari na uamuzi wa njia ya usimamizi, sio tathmini ya thamani au ubaguzi dhidi ya uhai wa ajabu</td></tr><tr><td>Kanuni ya Sasisho la Mwisho</td><td>Kadri ujuzi kuhusu uhai wa ajabu unavyozidi kina, vigezo vya utambuzi vinapasishwa kwa kasi, kuepuka ugumu wa uainishaji wa kudumu</td></tr><tr><td>Kanuni ya Kipaumbele cha Asili</td><td>Wakati hatari iko katika udhibiti, kuunganisha uhai wa ajabu katika utaratibu wa asili kunapendelewa, badala ya kuziharibu kwa upofu</td></tr></tbody></table><h2 id="_3-vipengele-na-vigezo-vya-utambuzi" tabindex="-1">3. Vipengele na Vigezo vya Utambuzi <a class="header-anchor" href="#_3-vipengele-na-vigezo-vya-utambuzi" aria-label="Permalink to &quot;3. Vipengele na Vigezo vya Utambuzi&quot;">​</a></h2><p>Utambuzi wa uhai wa ajabu unafanyika kutoka vipengele sifaa vifuatavyo, na vigezo vya tathmini maalum vinawekwa kwa kila kipengele:</p><h3 id="a-kipengele-cha-umbo-la-uhai" tabindex="-1">(A) Kipengele cha Umbo la Uhai <a class="header-anchor" href="#a-kipengele-cha-umbo-la-uhai" aria-label="Permalink to &quot;(A) Kipengele cha Umbo la Uhai&quot;">​</a></h3><p>Kutathmini muundo wa nyenzo na umbo wa kuwepo wa uhai wa ajabu:</p><ol><li><strong>Muundo wa Nyenzo</strong>: Je, imeundwa na vipengele au nishati gani, je, inafuata sheria za nyenzo zilizopo.</li><li><strong>Umbo wa Kuwepo</strong>: Umbo wa nyenzo, umbo wa nishati, umbo wa taarifa, au umbo wa mchanganyiko.</li><li><strong>Uthabiti wa Umbo</strong>: Je, umbo ni thabiti, je, hubadilika kwa hiari au chini ya ushawishi wa nje.</li><li><strong>Kiwango cha Mwili</strong>: Anuwai ya ukubwa wa mwili, je, inabadilika au ni thabiti.</li><li><strong>Mzunguko wa Maisha</strong>: Je, ina hatua za maisha kama vile kuzaliwa, kukua, kuzalisha, kufa, n.k., muda wa maisha.</li></ol><h3 id="b-kipengele-cha-sifa-za-nishati" tabindex="-1">(B) Kipengele cha Sifa za Nishati <a class="header-anchor" href="#b-kipengele-cha-sifa-za-nishati" aria-label="Permalink to &quot;(B) Kipengele cha Sifa za Nishati&quot;">​</a></h3><p>Kutathmini sifa za nishati na kiwango cha nishati cha uhai wa ajabu:</p><table tabindex="0"><thead><tr><th>Kipengele cha Tathmini</th><th>Kigezo</th></tr></thead><tbody><tr><td>Aina ya Nishati</td><td>Je, ni aina ya nishati iliyopo au aina ya nishati isiyojulikana, je, sifa za nishati ni za kuvutia au za kuzuia</td></tr><tr><td>Kiwango cha Nishati</td><td>Uzito wa nishati na kiwango cha nguvu, kutoka kiwango cha kwanza (dhaifu) hadi kiwango cha kumi (ya ulimwengu)</td></tr><tr><td>Uthabiti wa Nishati</td><td>Je, nishati ni thabiti, je, kuna hatari ya kupoteza udhibiti au kulipuka kwa hiari</td></tr><tr><td>Uvutaji wa Nishati</td><td>Kiwango cha uvutaji na nishati ya roho ya anga-dunia, nishati ya asili, je, inaweza kufanywa kuzingatia na kubadilishwa</td></tr><tr><td>Uchafuzi wa Nishati</td><td>Je, husababisha uchafuzi au athari ya uharibifu katika mazingira ya nishati ya karibu</td></tr><tr><td>Uambukizi wa Nishati</td><td>Je, nishati inaambukiza, je, inaweza kuambukiza au kubadilisha uhai mwingine</td></tr></tbody></table><h3 id="c-kipengele-cha-kiwango-cha-fahamu" tabindex="-1">(C) Kipengele cha Kiwango cha Fahamu <a class="header-anchor" href="#c-kipengele-cha-kiwango-cha-fahamu" aria-label="Permalink to &quot;(C) Kipengele cha Kiwango cha Fahamu&quot;">​</a></h3><p>Kutathmini kiwango cha fahamu na akili wa uhai wa ajabu:</p><ol><li><strong>Uwezo wa Fahamu</strong>: Je, ina uwezo wa kufahamu ulimwengu wa nje, anuwai na njia ya ufahamu.</li><li><strong>Fahamu ya Nafsi</strong>: Je, ina fahamu ya nafsi na utambuzi wa nafsi, je, inaweza kutofautisha nafsi yake na ulimwengu wa nje.</li><li><strong>Kiwango cha Akili</strong>: Uwezo wa kujifunza, uwezo wa hoja ya kimantiki, kiwango cha uwezo wa kutatua matatizo.</li><li><strong>Uwezo wa Hisia</strong>: Je, ina uzoefu wa hisia, aina na ukubwa wa hisia.</li><li><strong>Uwezo wa Mawasiliano</strong>: Je, inaweza kuwasiliana na uhai mwingine, njia na ufanisi wa mawasiliano.</li><li><strong>Utambuzi wa Maadili</strong>: Je, ina uwezo wa hukumu ya maadili, je, inaweza kuelewa falsafa ya asili na kanuni za kisheria.</li></ol><h3 id="d-kipengele-cha-mtindo-wa-tabia" tabindex="-1">(D) Kipengele cha Mtindo wa Tabia <a class="header-anchor" href="#d-kipengele-cha-mtindo-wa-tabia" aria-label="Permalink to &quot;(D) Kipengele cha Mtindo wa Tabia&quot;">​</a></h3><p>Kutathmini sifa za tabia na mwelekeo wa tabia wa uhai wa ajabu:</p><ul><li><strong>Ushirikishaji</strong>: Je, ina mwelekeo wa kushambulia kwa hiari uhai mwingine, hali ya kichocheo cha shambulio na njia ya shambulio.</li><li><strong>Mwelekeo wa Uharibu</strong>: Je, ina mtindo wa tabia wa kuiba nishati au rasilimali za uhai mwingine.</li><li><strong>Ujamaa</strong>: Je, ina tabia za kijamii, je, inaisha peke yake au kwa kundi, muundo wa kijamii ni upi.</li><li><strong>Njia ya Kuzalisha</strong>: Njia na kasi ya kuzalisha, je, kuna hatari ya kuzalisha kwa kuzidisha.</li><li><strong>Tabia ya Uhamiaji</strong>: Je, ina tabia ya uhamiaji au upanuzi, anuwai na kasi ya upanuzi.</li><li><strong>Mwitikazio wa Msisimko</strong>: Aina ya mwitikazio inapokutana na tishio au vichocheo, je, husababisha uharibifu usio na udhibiti.</li></ul><h3 id="e-kipengele-cha-athari-ya-mazingira" tabindex="-1">(E) Kipengele cha Athari ya Mazingira <a class="header-anchor" href="#e-kipengele-cha-athari-ya-mazingira" aria-label="Permalink to &quot;(E) Kipengele cha Athari ya Mazingira&quot;">​</a></h3><p>Kutathmini athari za uhai wa ajabu kwenye mazingira ya karibu:</p><ol><li><strong>Athari ya Mazingira</strong>: Athari kwenye mfumo wa mazingira wa eneo hilo, je, huvunja usawa wa mazingira.</li><li><strong>Athari ya Nishati</strong>: Athari kwenye mazingira ya nishati ya karibu, je, husababisha usumbufu au ukosefu wa nishati.</li><li><strong>Athari ya Nafasi</strong>: Athari kwenye muundo wa nafasi, je, husababisha mapasuko ya nafasi au utotowaji wa nafasi.</li><li><strong>Athari ya Sheria</strong>: Athari kwenye sheria za ulimwengu, je, huingilia au hugeuza uendeshaji wa sheria za eneo hilo.</li><li><strong>Athari ya Uchafuzi</strong>: Je, husababisha uchafuzi wa nyenzo, nishati, au taarifa, anuwai na muda wa uchafuzi.</li></ol><h3 id="f-kipengele-cha-uwezekano-wa-asili" tabindex="-1">(F) Kipengele cha Uwezekano wa Asili <a class="header-anchor" href="#f-kipengele-cha-uwezekano-wa-asili" aria-label="Permalink to &quot;(F) Kipengele cha Uwezekano wa Asili&quot;">​</a></h3><p>Kutathmini uwezekano wa kuunganisha uhai wa ajabu katika utaratibu wa asili:</p><table tabindex="0"><thead><tr><th>Kipengele cha Tathmini</th><th>Kigezo</th></tr></thead><tbody><tr><td>Uwezekano wa Mawasiliano</td><td>Je, inaweza kuanzisha njia za mawasiliano zinazofaa</td></tr><tr><td>Kukubaliwa kwa Falsafa</td><td>Je, inaweza kuelewa na kukubali falsafa ya asili</td></tr><tr><td>Uwezekano wa Ushirikiano</td><td>Je, inaweza kushirikiana na kusaidiana na uhai mwingine</td></tr><tr><td>Mchango wa Thamani</td><td>Mchango na thamani inayowezekana baada ya kuunganishwa katika utaratibu wa asili</td></tr><tr><td>Ugumu wa Uunganisho</td><td>Ugumu na muda unaohitajika kwa kuunganishwa katika utaratibu wa asili uliopo</td></tr><tr><td>Uthabiti wa Muda Mrefu</td><td>Uthabiti na uendelevu wa uhusiano wa simbiosis wa muda mrefu</td></tr></tbody></table><h3 id="g-kipengele-cha-kiwango-cha-hatari" tabindex="-1">(G) Kipengele cha Kiwango cha Hatari <a class="header-anchor" href="#g-kipengele-cha-kiwango-cha-hatari" aria-label="Permalink to &quot;(G) Kipengele cha Kiwango cha Hatari&quot;">​</a></h3><p>Kwa kuzingatia matokeo ya tathmini ya vipengele vyote vya juu, kiwango cha hatari cha uhai wa ajabu kinabainishwa:</p><table tabindex="0"><thead><tr><th>Kiwango cha Hatari</th><th>Jina</th><th>Kigezo cha Uamuzi</th><th>Mwelekeo wa Usimamizi</th></tr></thead><tbody><tr><td>Kiwango cha Kwanza</td><td>Hatari Ndogo</td><td>Kiwango cha fahamu cha juu, hakuna ushirikishaji, athari ya mazingira inaweza kudhibitiwa, uwezekano wa asili wa juu</td><td>Usimamizi wa aina ya simbiosis ya urafiki</td></tr><tr><td>Kiwango cha Pili</td><td>Hatari ya Kati</td><td>Kiwango cha fahamu cha kati, ina baadhi ya ushirikishaji au athari ya mazingira, inahitaji mwongozo na uchunguzi</td><td>Usimamizi wa aina ya utengamano wa uchunguzi</td></tr><tr><td>Kiwango cha Tatu</td><td>Hatari Kubwa</td><td>Kiwango cha fahamu cha chini au kisichoweza kufika, ushirikishaji wenye nguvu, uharibifu wa mazingira mkubwa, uwezekano wa asili wa chini</td><td>Usimamizi wa aina ya ukomeshaji-mabadiliko</td></tr><tr><td>Kiwango cha Nne</td><td>Hatari Kubwa Sana</td><td>Ina uwezo wa uharibifu wa ulimwengu, mawasiliano haiwezekani, haina udhibiti, inatishia uhai wa ustaarabu</td><td>Ukomeshaji wa dharura + ripoti</td></tr></tbody></table><h2 id="_4-mchakato-wa-utambuzi" tabindex="-1">4. Mchakato wa Utambuzi <a class="header-anchor" href="#_4-mchakato-wa-utambuzi" aria-label="Permalink to &quot;4. Mchakato wa Utambuzi&quot;">​</a></h2><p>Utambuzi wa uhai wa ajabu unafuata mchakato uliofananishwa ufuatao:</p><ol><li><strong>Ripoti ya Ugunduzi</strong>: Baada ya shirika au mtu yeyote kugundua uhai wa ajabu, lazima aripoti mara moja kwa shirika la usimamizi wa uhai la eneo hilo.</li><li><strong>Utengamano wa Awali</strong>: Shirika la usimamizi wa uhai baada ya kupata ripoti, lazima litetengamane mara moja kwa awali uhai wa ajabu, ili kuzuia uliene au usababize madhara.</li><li><strong>Uanzishaji wa Timu ya Utambuzi</strong>: Kuunda timu ya utambuzi inayojumuisha wanabiolojia, wanaojifunza, wawakilishi wa kabila za nje, wataalamu wa kisheria, n.k.</li><li><strong>Tathmini ya Vipengele Vingi</strong>: Timu ya utambuzi inafanya tathmani kamili ya uhai wa ajabu kulingana na vipengele sifaa, inaandika ripoti ya tathmini.</li><li><strong>Uainishaji wa Hatari</strong>: Kubaini kiwango cha hatari kulingana na matokeo ya tathmini, kutoa mapendekezo ya usimamizi.</li><li><strong>Uidhinishaji wa Idhini</strong>: Ripoti ya tathmini na mapendekezo ya usimamizi yanatumwa kwa shirika la juu la usimamizi wa uhai kwa ajili ya uidhinishaji, na juu ya hatari kubwa lazima iripotiwe kwa hakimu wa uhai wa ajabu wa Korti Kuu ya Asili.</li><li><strong>Utekelezaji wa Usimamizi</strong>: Kutekeleza usimamizi kulingana na mpango wa usimamizi ulioidhinishwa, kurekodi mchakato kamili wa usimamizi.</li><li><strong>Uchunguzi wa Ufuatiliaji</strong>: Baada ya usimamizi kukamilika, kufanya uchunguzi wa ufuatiliaji, kutathmini athari ya usimamizi, kurekebisha mpango wa usimamizi inapohitajika.</li></ol><h2 id="_5-mashirika-na-wafanyakazi-wa-utambuzi" tabindex="-1">5. Mashirika na Wafanyakazi wa Utambuzi <a class="header-anchor" href="#_5-mashirika-na-wafanyakazi-wa-utambuzi" aria-label="Permalink to &quot;5. Mashirika na Wafanyakazi wa Utambuzi&quot;">​</a></h2><ul><li><strong>Ofisi ya Usimamizi wa Uhai</strong>: Shirika maalum cha usimamizi wa uhai wa ajabu kilichoundwa na serikali, kinachohusika na utambuzi, usajili, usimamizi na uchunguzi wa uhai wa ajabu.</li><li><strong>Timu ya Wataalamu wa Utambuzi</strong>: Timu ya utambuzi inayojumuisha wataalamu kutoka nyanja mbalimbali, inayohusika na kazi maalum ya tathmini ya utambuzi.</li><li><strong>Timu ya Usimamizi wa Eneo</strong>: Inayohusika na utengamano wa eneo, udhibiti na utekelezaji wa usimamizi wa uhai wa ajabu, imejengwa na vifaa vya kitaalamu na hatua za ulinzi.</li><li><strong>Hakimu wa Uhai wa Ajabu</strong>: Hakimu maalum aliyeandaliwa na korti ya asili, anayohusika na mizozo ya kisheria inayohusiana na uhai wa ajabu na hakiki ya kisheria ya usimamizi wa hatari kubwa.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Vigezo vya utambuzi wa uhai wa ajabu ni ulinzi wa kisayansi wa Ustaarabu wa Simbiosis wa Mtego katika kukabiliwa na aina za uhai zisizojulikana. Kwa kuanzisha mfumo wa tathmini ya vipengele vingi, mfumo wa viwango vya hatari, na mchakato wa utambuzi uliofananishwa, inahakikishwa kuwa ujuzi kuhusu uhai wa ajabu ni kamili, tathmini ni sahihi, na usimamizi ni unafaa, kulinda usalama wa asili wakati huo huo ikihifadhi njia za kuunganisha aina mpya za uhai zenye uwezekano katika utaratibu wa asili, ikiwa inaonyesha hekima ya utawala ya &quot;mwangalifu lakini si ya kuzuia, salama lakini si ya kufunga&quot;.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>54-奇特生命三类处置流程 (Mchakato wa usimamizi wa aina tatu za uhai wa ajabu)</li><li>50-万族谱系总览 (Muhtasari wa nasaba za kabila zote)</li><li>57-黑暗置换体起源与本质 (Asili na kiini cha mwili wa uingizwaji wa giza)</li><li>46-环境保护法 (Kanuni ya ulinzi wa mazingira)</li></ul>',40)])])}const z=i(h,[["render",e]]);export{r as __pageData,z as default};
